  ?z rdfs:label "DataCenter_basement_ZN_6" .
  ?p a ?class .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts . }
}

SELECT ?p ?class ?ts ?lab WHERE {
  ?z rdfs:label "DataCenter_basement_ZN_6" .
  ?z a brick:Room .
  ?p brick:isLocationOf ?z .
  ?p a ?class .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts . }
}

SELECT ?p ?class ?ts ?ext WHERE {
  ?p brick:isLocationOf ?z .
  ?p a brick:AirTemperatureSensor .
  ?z rdfs:label "DataCenter_basement_ZN_6" .
}

SELECT ?class ?ts ?ext ?lab WHERE {
  ?p a ?class .
  ?p rdfs:label "Zone_F2_Z06.Zone_Air_Temperature_Sensor" .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts . }
  OPTIONAL { ?p ref:hasExternalReference ?ext . }
}

