  ?p a ?class .
  ?p rdfs:label ?lab .
  FILTER(CONTAINS(str(?lab), "Zone_F2_Z06.Zone_Air_Temperature_Sensor"))
  OPTIONAL { ?p ref:hasTimeseriesId ?ts . }
